1225	+public class SeedDataImporter(AppDbContext db)
1226	+{
1227	+    private static readonly JsonSerializerOptions JsonOptions = new() { PropertyNameCaseInsensitive = true };
1228	+
1229	+    public async Task ImportIfEmptyAsync(string jsonFilePath, CancellationToken ct = default)
1230	+    {
1231	+        if (await db.Venues.AnyAsync(ct))
1232	+        {
1233	+            return;
1234	+        }
1235	+
1236	+        if (!File.Exists(jsonFilePath))
1237	+        {
1238	+            throw new InvalidOperationException($"Anfangsdatenbestand '{jsonFilePath}' wurde nicht gefunden.");
1239	+        }
1240	+
1241	+        var json = await File.ReadAllTextAsync(jsonFilePath, ct);
1242	+        var data = JsonSerializer.Deserialize<SeedDataDto>(json, JsonOptions)
1243	+            ?? throw new InvalidOperationException($"Anfangsdatenbestand konnte nicht aus '{jsonFilePath}' gelesen werden.");
1244	+
1245	+        await ImportAsync(data, ct);
1246	+    }
1247	+
1248	+    public async Task ImportAsync(SeedDataDto data, CancellationToken ct = default)
1249	+    {
1250	+        var venues = new List<Venue>();
1251	+        var venueIds = data.Spielstaetten.Select(v => v.Id).ToHashSet();
1252	+
1253	+        foreach (var eventDto in data.Veranstaltungen)
1254	+        {
1255	+            if (!venueIds.Contains(eventDto.SpielstaetteId))
