1248	+    public async Task ImportAsync(SeedDataDto data, CancellationToken ct = default)
1249	+    {
1250	+        var venues = new List<Venue>();
1251	+        var venueIds = data.Spielstaetten.Select(v => v.Id).ToHashSet();
1252	+
1253	+        foreach (var eventDto in data.Veranstaltungen)
1254	+        {
1255	+            if (!venueIds.Contains(eventDto.SpielstaetteId))
1256	+            {
1257	+                throw new InvalidOperationException(
1258	+                    $"Veranstaltung '{eventDto.Id}' referenziert unbekannte Spielstätte '{eventDto.SpielstaetteId}'.");
1259	+            }
1260	+        }
1261	+
1262	+        foreach (var venueDto in data.Spielstaetten)
1263	+        {
1264	+            var venue = new Venue { Name = venueDto.Name };
1265	+            var roomsById = new Dictionary<string, Room>();
1266	+
1267	+            foreach (var roomDto in venueDto.Raeume)
1268	+            {
1269	+                if (!roomsById.TryAdd(roomDto.Id, new Room
1270	+                {
1271	+                    Name = roomDto.Name,
1272	+                    RowLabels = roomDto.Reihen,
1273	+                    ColumnCount = roomDto.Spalten,
1274	+                    AisleColumns = roomDto.Gang?.Spalten ?? new List<int>(),
1275	+                }))
1276	+                {
1277	+                    throw new InvalidOperationException(
1278	+                        $"Spielstätte '{venueDto.Id}' enthält den Raum '{roomDto.Id}' mehrfach.");
1279	+                }
1280	+
1281	+                venue.Rooms.Add(roomsById[roomDto.Id]);
1282	+            }
1283	+
1284	+            foreach (var eventDto in data.Veranstaltungen.Where(e => e.SpielstaetteId == venueDto.Id))
1285	+            {
1286	+                if (!roomsById.TryGetValue(eventDto.RaumId, out var room))
1287	+                {
1288	+                    throw new InvalidOperationException(
1289	+                        $"Veranstaltung '{eventDto.Id}' referenziert unbekannten Raum '{eventDto.RaumId}' in Spielstätte '{venueDto.Id}'.");
1290	+                }
1291	+
1292	+                var @event = new Event
1293	+                {
1294	+                    Titel = eventDto.Titel,
1295	+                    Beschreibung = eventDto.Beschreibung,
1296	+                    Zeitpunkt = eventDto.Zeitpunkt,
1297	+                    DauerMinuten = eventDto.DauerMinuten,
1298	+                    Altersfreigabe = eventDto.Altersfreigabe,
1299	+                };
1300	+
1301	+                foreach (var priceCategoryDto in eventDto.Preiskategorien)
1302	+                {
1303	+                    @event.PriceCategories.Add(new PriceCategory
1304	+                    {
1305	+                        Name = priceCategoryDto.Name,
1306	+                        Preis = priceCategoryDto.Preis,
1307	+                    });
1308	+                }
1309	+
1310	+                var gesehen = new HashSet<(string RowLabel, int ColumnNumber)>();
1311	+                foreach (var sitzplatz in eventDto.BelegteSitzplaetze)
1312	+                {
1313	+                    var (rowLabel, columnNumber) = ParseSitzplatz(sitzplatz);
1314	+
1315	+                    if (!gesehen.Add((rowLabel, columnNumber)))
1316	+                    {
1317	+                        throw new InvalidOperationException(
1318	+                            $"Veranstaltung '{eventDto.Id}' listet den Sitzplatz '{sitzplatz}' mehrfach in 'belegteSitzplaetze'.");
1319	+                    }
1320	+
1321	+                    if (!room.RowLabels.Contains(rowLabel) || columnNumber < 1 || columnNumber > room.ColumnCount)
1322	+                    {
1323	+                        throw new InvalidOperationException(
1324	+                            $"Veranstaltung '{eventDto.Id}': Sitzplatz '{sitzplatz}' liegt außerhalb des Sitzplans von Raum '{eventDto.RaumId}'.");
1325	+                    }
1326	+
1327	+                    if (room.AisleColumns.Contains(columnNumber))
1328	+                    {
1329	+                        throw new InvalidOperationException(
1330	+                            $"Veranstaltung '{eventDto.Id}': Sitzplatz '{sitzplatz}' liegt auf einer Gang-Spalte von Raum '{eventDto.RaumId}'.");
1331	+                    }
1332	+
1333	+                    @event.BookingPositions.Add(new BookingPosition
1334	+                    {
1335	+                        RowLabel = rowLabel,
1336	+                        ColumnNumber = columnNumber,
1337	+                        BookingId = null,
1338	+                        PriceCategoryId = null,
1339	+                        CancelledAtUtc = null,
1340	+                    });
1341	+                }
1342	+
