1353	+    /// <summary>Führende Buchstaben = RowLabel, folgende Ziffern = ColumnNumber (z. B. "B3" -> ("B", 3)).</summary>
1354	+    internal static (string RowLabel, int ColumnNumber) ParseSitzplatz(string sitzplatz)
1355	+    {
1356	+        var digitsStart = 0;
1357	+        while (digitsStart < sitzplatz.Length && char.IsAsciiLetter(sitzplatz[digitsStart]))
1358	+        {
1359	+            digitsStart++;
1360	+        }
1361	+
1362	+        var digitsEnd = digitsStart;
1363	+        while (digitsEnd < sitzplatz.Length && char.IsAsciiDigit(sitzplatz[digitsEnd]))
1364	+        {
1365	+            digitsEnd++;
1366	+        }
1367	+
1368	+        if (digitsStart == 0 || digitsStart == sitzplatz.Length || digitsEnd != sitzplatz.Length)
1369	+        {
1370	+            throw new FormatException($"Sitzplatz '{sitzplatz}' entspricht nicht dem Format <Reihenbuchstaben><Spaltenzahl>.");
1371	+        }
1372	+
1373	+        var rowLabel = sitzplatz[..digitsStart];
1374	+        var columnNumber = int.Parse(sitzplatz[digitsStart..]);
1375	+        return (rowLabel, columnNumber);
1376	+    }
1377	+}
