1896	+using Microsoft.Data.SqlClient;
1897	+using Microsoft.EntityFrameworkCore;
1898	+using seed_a_backend.Api.Infrastructure;
1899	+
1900	+namespace seed_a_backend.Tests;
1901	+
1902	+/// <summary>
1903	+/// Erstellt für jede Testklasse eine eigene, eindeutig benannte Testdatenbank auf dem echten
1904	+/// SQL Server aus ConnectionStrings__Default (Consistency Convention „Test-Engine für
1905	+/// Nebenläufigkeit“ — kein EF-Core-InMemory-Provider, da gefilterte Unique-Constraints sonst
1906	+/// nicht durchgesetzt würden). Schema wird über die echten EF-Core-Migrations aufgebaut, damit
1907	+/// die Migration selbst mitgetestet wird.
1908	+/// </summary>
1909	+public sealed class SqlServerTestDatabase : IAsyncLifetime
1910	+{
1911	+    private readonly string _connectionString;
1912	+
1913	+    public SqlServerTestDatabase()
1914	+    {
1915	+        var baseConnectionString = Environment.GetEnvironmentVariable("ConnectionStrings__Default")
1916	+            ?? throw new InvalidOperationException("ConnectionStrings__Default ist für die Tests nicht gesetzt.");
1917	+
1918	+        var builder = new SqlConnectionStringBuilder(baseConnectionString)
1919	+        {
1920	+            InitialCatalog = $"seed_a_test_{Guid.NewGuid():N}",
1921	+        };
1922	+        _connectionString = builder.ConnectionString;
1923	+    }
1924	+
1925	+    public AppDbContext CreateContext()
1926	+    {
1927	+        var options = new DbContextOptionsBuilder<AppDbContext>()
1928	+            .UseSqlServer(_connectionString)
1929	+            .Options;
1930	+        return new AppDbContext(options);
1931	+    }
1932	+
1933	+    public async ValueTask InitializeAsync()
1934	+    {
1935	+        await using var db = CreateContext();
1936	+        await db.Database.MigrateAsync();
1937	+    }
1938	+
1939	+    public async ValueTask DisposeAsync()
1940	+    {
1941	+        await using var db = CreateContext();
1942	+        await db.Database.EnsureDeletedAsync();
1943	+    }
1944	+}
