1251	+        var venueIds = data.Spielstaetten.Select(v => v.Id).ToHashSet();
1252	+
1253	+        foreach (var eventDto in data.Veranstaltungen)
1254	+        {
1255	+            if (!venueIds.Contains(eventDto.SpielstaetteId))
