1265	+            var roomsById = new Dictionary<string, Room>();
1266	+
1267	+            foreach (var roomDto in venueDto.Raeume)
1268	+            {
1269	+                if (!roomsById.TryAdd(roomDto.Id, new Room
1270	+                {
1271	+                    Name = roomDto.Name,
1272	+                    RowLabels = roomDto.Reihen,
1273	+                    ColumnCount = roomDto.Spalten,
