1311	+                foreach (var sitzplatz in eventDto.BelegteSitzplaetze)
1312	+                {
1313	+                    var (rowLabel, columnNumber) = ParseSitzplatz(sitzplatz);
1314	+
1315	+                    if (!gesehen.Add((rowLabel, columnNumber)))
1316	+                    {
1317	+                        throw new InvalidOperationException(
